// apply-release-signing.mjs
//
// Injects a release `signingConfigs` block plus `buildTypes.release.signingConfig`
// into the GENERATED `android/app/build.gradle`.
//
// Why a script instead of a committed gradle file?
//   `apps/mobile/android/` is gitignored (it is regenerated by `npx cap add android`
//   and rewritten by `npx cap sync`). We therefore cannot commit the signing config
//   directly. Instead we commit this script + templates and re-apply the config after
//   every sync.
//
// Idempotent: if the marker (MAPS_RELEASE_SIGNING) is already present, it exits
// without changing anything. A fresh `cap sync` overwrites build.gradle (removing the
// marker), so re-running after sync re-applies cleanly.
//
// Secrets: no passwords are baked into build.gradle. The injected block reads
// `apps/mobile/keystore.properties` at Gradle build time. If that file is absent,
// the signingConfig is left empty and `assembleRelease` produces an UNSIGNED apk.
//
// Usage:  node scripts/apply-release-signing.mjs
// Run from apps/mobile/ (npm scripts already set that cwd).

import { readFileSync, writeFileSync, existsSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'

const MARKER = 'MAPS_RELEASE_SIGNING'

const scriptDir = dirname(fileURLToPath(import.meta.url))
const mobileDir = join(scriptDir, '..')
const gradlePath = join(mobileDir, 'android', 'app', 'build.gradle')

/** The signingConfigs { release { ... } } block inserted just inside `android {`. */
const SIGNING_CONFIGS_BLOCK = `
    // === ${MARKER}: injected by scripts/apply-release-signing.mjs — do not edit by hand ===
    // Reads apps/mobile/keystore.properties at build time. Copy keystore.properties.example
    // to keystore.properties and fill in real values before running assembleRelease.
    signingConfigs {
        release {
            def keystorePropertiesFile = rootProject.file("../keystore.properties")
            if (keystorePropertiesFile.exists()) {
                def keystoreProperties = new Properties()
                keystorePropertiesFile.withInputStream { keystoreProperties.load(it) }
                def storeFilePath = keystoreProperties['storeFile']
                storeFile new File(storeFilePath).isAbsolute() ? file(storeFilePath) : rootProject.file("../" + storeFilePath)
                storePassword keystoreProperties['storePassword']
                keyAlias keystoreProperties['keyAlias']
                keyPassword keystoreProperties['keyPassword']
            } else {
                println("[${MARKER}] WARNING: apps/mobile/keystore.properties not found — release APK will be UNSIGNED.")
            }
        }
    }
    // === END ${MARKER} ===
`

function fail(msg) {
  console.error(`[apply-release-signing] ERROR: ${msg}`)
  process.exit(1)
}

if (!existsSync(gradlePath)) {
  fail(
    `${gradlePath} not found.\n` +
      `  Generate the Android project first:\n` +
      `    npm run cap:add:android   (once)\n` +
      `    npx cap sync android`,
  )
}

let gradle = readFileSync(gradlePath, 'utf8')

if (gradle.includes(MARKER)) {
  console.log('[apply-release-signing] Signing config already present — nothing to do.')
  process.exit(0)
}

// 1) Insert the signingConfigs block immediately after the opening `android {`.
const androidOpen = gradle.match(/android\s*\{/)
if (!androidOpen) {
  fail('Could not locate the `android {` block in build.gradle.')
}
const insertAt = androidOpen.index + androidOpen[0].length
gradle = gradle.slice(0, insertAt) + SIGNING_CONFIGS_BLOCK + gradle.slice(insertAt)

// 2) Add `signingConfig signingConfigs.release` inside `buildTypes { release { ... } }`.
const releaseBlock = gradle.match(/buildTypes\s*\{\s*release\s*\{/)
if (!releaseBlock) {
  fail(
    'Could not locate `buildTypes { release { ... } }` in build.gradle.\n' +
      '  The signingConfigs block was inserted but no build type references it.',
  )
}
const releaseInsertAt = releaseBlock.index + releaseBlock[0].length
gradle =
  gradle.slice(0, releaseInsertAt) +
  '\n            signingConfig signingConfigs.release' +
  gradle.slice(releaseInsertAt)

writeFileSync(gradlePath, gradle, 'utf8')
console.log('[apply-release-signing] Release signing config applied to android/app/build.gradle.')
